let cases=[];let selected="HHG-014";let filter="all";
const $=s=>document.querySelector(s);const esc=s=>String(s??"").replace(/[&<>"']/g,m=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[m]));
const money=n=>new Intl.NumberFormat("en-US",{style:"currency",currency:"USD"}).format(n);
function visible(){const q=$("#search").value.toLowerCase();return cases.filter(x=>(filter==="all"||x.case.verdict===filter)&&[x.case_id,x.trigger.card_id,x.case.pattern].join(" ").toLowerCase().includes(q))}
function renderList(){const list=visible();$("#queueCount").textContent=list.length;$("#caseList").innerHTML=list.map(x=>`<div class="case-row ${x.case_id===selected?'active':''}" data-id="${x.case_id}" tabindex="0"><span class="case-dot ${x.case.verdict}"></span><div><b>${x.case_id}</b><small>${esc(x.case.pattern.replaceAll('_',' '))} · ${esc(x.trigger.card_id)}</small></div><span class="risk">${Math.round(x.case.fraud_probability*100)}%</span></div>`).join("");document.querySelectorAll('.case-row').forEach(el=>{const go=()=>{selected=el.dataset.id;renderList();renderDetail()};el.onclick=go;el.onkeydown=e=>{if(e.key==='Enter')go()}})}
function graphMarkup(x){const label=x.trigger.card_id;const device=x.case.connected_device_profiles[0]||"baseline";const prior=x.case.similar_prior_cases[0]||"policy R1";return `<div class="graph"><span class="edge" style="width:170px;left:94px;top:105px;transform:rotate(-18deg)"></span><span class="edge" style="width:175px;left:222px;top:62px;transform:rotate(27deg)"></span><span class="edge" style="width:150px;left:215px;top:150px;transform:rotate(-11deg)"></span><span class="node primary" style="left:30px;top:88px">${esc(x.trigger.flagged_txn_id)}</span><span class="node device" style="left:190px;top:35px">${esc(device.slice(0,28))}</span><span class="node" style="left:185px;top:136px">${esc(label)}</span><span class="node case" style="right:22px;top:91px">${esc(prior)}</span></div>`}
function renderDetail(){const x=cases.find(c=>c.case_id===selected)||visible()[0];if(!x)return;selected=x.case_id;const c=x.case;$("#caseDetail").innerHTML=`<header class="detail-head"><div><span class="eyebrow">${esc(x.trigger.type.replace('_',' '))} · ${esc(x.case_id)}</span><h2>${esc(c.pattern.replaceAll('_',' '))}</h2><div class="sub">${esc(x.trigger.card_id)} · TXN ${esc(x.trigger.flagged_txn_id)} · ${esc(x.trigger.opened_at)}</div></div><span class="verdict ${c.verdict}">${c.verdict} · ${Math.round(c.fraud_probability*100)}%</span></header><div class="metrics"><div class="metric"><span>EXPOSURE</span><b>${money(c.exposure_usd)}</b></div><div class="metric"><span>TRANSACTIONS</span><b>${c.affected_txn_ids.length||'—'}</b></div><div class="metric"><span>PRIOR CASES</span><b>${c.similar_prior_cases.length}</b></div><div class="metric"><span>SAR</span><b>${x.sar.file?'FILE':'NO FILE'}</b></div></div><div class="grid"><div><section class="card"><h3>ANALYST BRIEF</h3><p class="summary">${esc(c.summary)}</p></section><section class="card actions"><h3>POLICY-CONSTRAINED ACTIONS</h3>${x.next_best_actions.final.map(a=>`<div class="action"><div><strong>${esc(a.action)}</strong><p>${esc(a.reason)}</p></div><span class="route">${esc(a.route)}</span></div>`).join('')}</section></div><div><section class="card"><h3>EVIDENCE SUBGRAPH</h3>${graphMarkup(x)}</section><section class="card actions"><h3>PROVENANCE</h3><ul class="evidence">${c.evidence.map(e=>`<li>${esc(e.claim)}<code>${esc(e.source)} · ${esc(e.ref)}</code></li>`).join('')}</ul></section></div></div>`}
async function init(){const res=await fetch('cases.json');cases=await res.json();$("#fraudCount").textContent=cases.filter(x=>x.case.verdict==='fraud').length;$("#legitCount").textContent=cases.filter(x=>x.case.verdict==='legitimate').length;$("#caseCount").textContent=cases.length;renderList();renderDetail()}
$("#search").addEventListener('input',renderList);document.querySelectorAll('.filter').forEach(b=>b.onclick=()=>{document.querySelectorAll('.filter').forEach(x=>x.classList.remove('active'));b.classList.add('active');filter=b.dataset.filter;renderList();if(!visible().some(x=>x.case_id===selected)&&visible()[0]){selected=visible()[0].case_id;renderDetail()}});$("#theme").onclick=()=>document.documentElement.classList.toggle('light');init().catch(()=>$("#caseDetail").innerHTML='<div class="loading">Could not load case evidence.</div>');
